# ---------------------------------------------------------------------------
# Backend — Ollama auto-start
# ---------------------------------------------------------------------------

def _known_ollama_paths() -> list:
    local = os.environ.get("LOCALAPPDATA", "")
    pf = os.environ.get("PROGRAMFILES", "")
    pfx86 = os.environ.get("PROGRAMFILES(X86)", "")
    programdata = os.environ.get("PROGRAMDATA", "")
    candidates = [
        r"C:\ollama-ipex\ollama.exe",
        os.path.join(local, "Programs", "Ollama", "ollama.exe"),
        os.path.join(pf, "Ollama", "ollama.exe"),
        os.path.join(pfx86, "Ollama", "ollama.exe"),
        os.path.join(programdata, "Ollama", "ollama.exe"),
    ]
    return [c for c in candidates if c and os.path.isfile(c)]

def _find_ollama_exe() -> Optional[str]:
    import shutil
    known = _known_ollama_paths()
    if known:
        return known[0]
    found = shutil.which("ollama") or shutil.which("ollama.exe")
    if found:
        return found
    for root in OLLAMA_SEARCH_DIRS:
        if not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            depth = dirpath.replace(root, "").count(os.sep)
            if depth > 3:
                dirnames.clear()
                continue
            for fname in filenames:
                if fname.lower() in ("ollama.exe", "ollama"):
                    return os.path.join(dirpath, fname)
    return None

def _ping(url: str) -> bool:
    try:
        urllib.request.urlopen(f"{url}/api/tags", timeout=3)
        return True
    except Exception:
        return False

_ollama_proc: Optional[subprocess.Popen] = None  # only set if WE started ollama

def ensure_ollama_running() -> bool:
    global _ollama_proc
    if _ping(OLLAMA_URL):
        return True  # already running (not ours) -> leave it alone on exit
    exe = _find_ollama_exe()
    if not exe:
        return False
    _ollama_proc = subprocess.Popen(
        [exe, "serve"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
    )
    for _ in range(15):
        time.sleep(1)
        if _ping(OLLAMA_URL):
            return True
    return False

def stop_ollama():
    """Terminate the Ollama server, but only if this app started it."""
    global _ollama_proc
    if _ollama_proc is None:
        return
    try:
        if sys.platform == "win32":
            # terminate() only kills ollama.exe itself; ollama serve spawns
            # child runner processes that keep the server alive. Kill the tree.
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(_ollama_proc.pid)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        else:
            _ollama_proc.terminate()
        try:
            _ollama_proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            _ollama_proc.kill()
    except Exception:
        pass
    finally:
        _ollama_proc = None

def list_models() -> List[str]:
    try:
        with urllib.request.urlopen(f"{OLLAMA_URL}/api/tags", timeout=5) as r:
            return [m["name"] for m in json.loads(r.read()).get("models", [])]
    except Exception:
        return []

def pick_model(preferred: str = "stheno") -> Optional[str]:
    """Only ever selects the required model — never falls back to any other
    model that happens to be installed."""
    available = list_models()
    for name in available:
        if preferred in name.lower() or name.lower().startswith(preferred.lower()):
            return name
    return None

# ---------------------------------------------------------------------------
# Session
# ---------------------------------------------------------------------------

@dataclass
class Message:
    role: str
    content: str
    def to_dict(self) -> dict:
        return {"role": self.role, "content": self.content}

@dataclass
class LelouchSession:
    model: str
    max_history: int
    max_tokens: int
    temperature: float
    stream: bool
    history: Deque[Message] = field(default_factory=deque)
    mood_hint: str = ""

    def add(self, role: str, content: str) -> None:
        self.history.append(Message(role, content))
        while len(self.history) > self.max_history * 2:
            self.history.popleft()

    def messages(self) -> List[dict]:
        sys_content = SYSTEM_PROMPT
        if self.mood_hint:
            sys_content += (
                f"\n## Right now\n"
                f"Lelouch is in {self.mood_hint} mode. Let this subtly colour his tone "
                f"and approach — do not state it outright, just let it show naturally.\n"
            )
        out = [{"role": "system", "content": sys_content}]
        out.extend(m.to_dict() for m in self.history)
        return out

# ---------------------------------------------------------------------------
# HTTP
# ---------------------------------------------------------------------------

class OllamaError(Exception):
    pass

def _token_from(obj: dict) -> str:
    return (obj.get("message", {}).get("content") or obj.get("response") or "")

def _stream(payload: dict, callback: Callable[[str], None], timeout: int = 120) -> str:
    payload = {**payload, "stream": True}
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        f"{OLLAMA_URL}/api/chat",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    chunks: List[str] = []
    with urllib.request.urlopen(req, timeout=timeout) as r:
        for raw in r:
            line = raw.strip()
            if not line:
                continue
            obj = json.loads(line)
            token = _token_from(obj)
            if token:
                callback(token)
                chunks.append(token)
            if obj.get("done"):
                break
    return "".join(chunks)

def _post(payload: dict, timeout: int = 120) -> dict:
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        f"{OLLAMA_URL}/api/chat",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode())

def chat(session: LelouchSession, user_input: str,
         stream_callback: Optional[Callable[[str], None]] = None) -> str:
    user_input = user_input.strip()
    if not user_input:
        return "Lelouch is listening. Speak with purpose."
    session.add("user", user_input)
    payload = {
        "model":    session.model,
        "messages": session.messages(),
        "options":  {"temperature": session.temperature, "num_predict": session.max_tokens},
        "stream":   False,
    }
    if session.stream and stream_callback:
        text = _stream(payload, callback=stream_callback)
    else:
        result = _post(payload)
        text = _token_from(result).strip()
        if not text:
            text = result.get("message", {}).get("content", "").strip()
    if not text:
        text = "Lelouch pauses. Say that again."
    text = _normalize_reply(text)
    session.add("assistant", text)
    return text

