class LelouchApp(tk.Tk):
    def __init__(self, session: LelouchSession):
        super().__init__()
        self.session        = session
        self.bond           = MentorTracker()
        self.history_log    = load_history()   # persistent log
        self.is_typing      = False
        self.current_mood   = "Neutral"
        self.stream_buffer  = ""
        self.lelouch_image      = None

        self.title("AI Lelouch — Code Geass Strategic Advisor")
        self.configure(bg=BG_DARK)
        self.geometry("1060x680")
        self.minsize(860, 560)

        # Load last N turns from persistent history into session memory
        self._restore_session_memory()

        self._load_lelouch_image()
        self._build_ui()
        self._post_greeting()

    def _restore_session_memory(self, max_turns: int = 20):
        """Feed recent chat history into the session so Lelouch remembers past talks."""
        if not self.history_log:
            return
        # Take last max_turns*2 entries (each turn = USER + LELOUCH)
        recent = self.history_log[-(max_turns * 2):]
        for entry in recent:
            role = "user" if entry.get("role") == "USER" else "assistant"
            self.session.add(role, entry.get("text", ""))

    # ------------------------------------------------------------------
    # Image loading
    # ------------------------------------------------------------------

    def _load_lelouch_image(self):
        """Load the embedded Lelouch avatar image from base64."""
        try:
            from PIL import Image, ImageTk
            import base64, io
            img_data = base64.b64decode(LELOUCH_IMAGE_B64)
            img = Image.open(io.BytesIO(img_data))
            img.thumbnail((200, 320), Image.LANCZOS)
            self.lelouch_image = ImageTk.PhotoImage(img)
            return
        except ImportError:
            pass
        self.lelouch_image = None

    # ------------------------------------------------------------------
    # UI Build
    # ------------------------------------------------------------------

    def _build_ui(self):
        # ── Header bar ──────────────────────────────────────────────
        header = tk.Frame(self, bg=HEADER_BG, height=52)
        header.pack(fill=tk.X, side=tk.TOP)
        header.pack_propagate(False)

        tk.Label(header, text="♟  Lelouch  ♟",
                 bg=HEADER_BG, fg=TITLE_CLR,
                 font=("Segoe UI", 15, "bold")).pack(side=tk.LEFT, padx=18, pady=10)

        self.mood_btn = tk.Button(
            header, text=f"  {self.current_mood} —  ",
            bg=NEUTRAL_BTN, fg="#ffffff",
            font=("Segoe UI", 10), relief=tk.FLAT,
            bd=0, padx=8, pady=4,
            cursor="hand2",
            command=self._change_mood
        )
        self.mood_btn.pack(side=tk.RIGHT, padx=14, pady=10)

        # ── Main content area ────────────────────────────────────────
        content = tk.Frame(self, bg=BG_DARK)
        content.pack(fill=tk.BOTH, expand=True)

        # Left: chat + input
        left_frame = tk.Frame(content, bg=BG_DARK)
        left_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # Chat canvas with scrollbar
        chat_outer = tk.Frame(left_frame, bg=BG_PANEL)
        chat_outer.pack(fill=tk.BOTH, expand=True)

        self.chat_canvas = tk.Canvas(chat_outer, bg=BG_PANEL,
                                     highlightthickness=0, bd=0)
        self.chat_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        scrollbar = tk.Scrollbar(chat_outer, orient=tk.VERTICAL,
                                  command=self.chat_canvas.yview)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
        self.chat_canvas.configure(yscrollcommand=scrollbar.set)
        self.chat_canvas.bind("<Configure>",
                               lambda e: self.chat_canvas.configure(
                                   scrollregion=self.chat_canvas.bbox("all")))

        self.messages_frame = tk.Frame(self.chat_canvas, bg=BG_PANEL)
        self.chat_canvas_window = self.chat_canvas.create_window(
            (0, 0), window=self.messages_frame, anchor="nw")
        self.chat_canvas.bind("<Configure>", self._on_canvas_resize)

        # Local scroll bindings — don't bleed into popup windows
        self.chat_canvas.bind("<MouseWheel>",
            lambda e: self.chat_canvas.yview_scroll(-1 * (e.delta // 120), "units"))
        self.messages_frame.bind("<MouseWheel>",
            lambda e: self.chat_canvas.yview_scroll(-1 * (e.delta // 120), "units"))

        # ── Input row ───────────────────────────────────────────────
        input_frame = tk.Frame(left_frame, bg=HEADER_BG, height=60)
        input_frame.pack(fill=tk.X, side=tk.BOTTOM)
        input_frame.pack_propagate(False)

        self.input_var = tk.StringVar()
        self.input_box = tk.Entry(
            input_frame, textvariable=self.input_var,
            bg=INPUT_BG, fg="#ffffff", insertbackground="#ffffff",
            relief=tk.FLAT, font=("Segoe UI", 11),
            bd=0
        )
        self.input_box.pack(side=tk.LEFT, fill=tk.BOTH, expand=True,
                            padx=(10, 6), pady=12)
        self.input_box.bind("<Return>", lambda e: self._send())

        def _make_btn(parent, text, cmd, icon=""):
            b = tk.Button(parent, text=f"{icon} {text}" if icon else text,
                          bg=BUTTON_SEND, fg="#ffffff",
                          font=("Segoe UI", 10, "bold"),
                          relief=tk.FLAT, bd=0,
                          padx=10, pady=6,
                          cursor="hand2",
                          activebackground="#4f6ee0",
                          activeforeground="#ffffff",
                          command=cmd)
            b.pack(side=tk.LEFT, padx=3, pady=10)
            return b

        _make_btn(input_frame, "Send",  self._send)
        _make_btn(input_frame, "⚙",    self._open_settings)
        _make_btn(input_frame, "Lore",  self._show_lore,  "📖")
        _make_btn(input_frame, "Hist",  self._show_history, "📋")
        _make_btn(input_frame, "Clear", self._clear_chat,  "🗑")

        # ── Status bar ──────────────────────────────────────────────
        self.status_var = tk.StringVar(value="Lelouch is listening. Speak with purpose.")
        status_bar = tk.Label(self, textvariable=self.status_var,
                              bg=HEADER_BG, fg=STATUS_CLR,
                              font=("Segoe UI", 9), anchor="w")
        status_bar.pack(fill=tk.X, side=tk.BOTTOM)

        # ── Right sidebar ────────────────────────────────────────────
        sidebar = tk.Frame(content, bg=SIDEBAR_BG, width=220)
        sidebar.pack(side=tk.RIGHT, fill=tk.Y)
        sidebar.pack_propagate(False)

        self._build_sidebar(sidebar)

    def _build_sidebar(self, sidebar: tk.Frame):
        # Avatar image area
        avatar_frame = tk.Frame(sidebar, bg=SIDEBAR_BG)
        avatar_frame.pack(fill=tk.X, padx=6, pady=(8, 2))

        if self.lelouch_image:
            img_label = tk.Label(avatar_frame, image=self.lelouch_image,
                                  bg=SIDEBAR_BG, relief=tk.FLAT)
            img_label.pack()
        else:
            # Placeholder blue box with text
            placeholder = tk.Canvas(avatar_frame, width=200, height=220,
                                     bg="#0f1a2b", highlightthickness=1,
                                     highlightbackground="#5b21b6")
            placeholder.pack()
            placeholder.create_text(100, 110, text="♟ Lelouch ♟",
                                     fill="#7dd3fc", font=("Segoe UI", 16, "bold"))

        self.avatar_status = tk.Label(
            sidebar, text="— observing in silence —",
            bg=SIDEBAR_BG, fg=MOOD_CLR,
            font=("Segoe UI", 9)
        )
        self.avatar_status.pack(pady=(2, 6))

        # ── Strategic Alignment Panel ──────────────────────────────────
        align_outer = tk.Frame(sidebar, bg="#110e1e", bd=0,
                                highlightthickness=1,
                                highlightbackground="#2e1a5a")
        align_outer.pack(fill=tk.X, padx=8, pady=(2, 6))

        # Header line
        hdr = tk.Frame(align_outer, bg="#160f28")
        hdr.pack(fill=tk.X)
        tk.Label(hdr, text="◈  STRATEGIC ALIGNMENT",
                 bg="#160f28", fg="#9b5fd4",
                 font=("Segoe UI", 8, "bold"),
                 anchor="w", padx=8, pady=5).pack(fill=tk.X)

        # Separator line
        tk.Frame(align_outer, bg="#2e1a5a", height=1).pack(fill=tk.X)

        body = tk.Frame(align_outer, bg="#110e1e")
        body.pack(fill=tk.X, padx=8, pady=6)

        def _stat_row(parent, label, val_pct, row):
            tk.Label(parent, text=label.upper(),
                     bg="#110e1e", fg="#666666",
                     font=("Segoe UI", 7, "bold"),
                     anchor="w").grid(row=row*2, column=0, columnspan=2,
                                      sticky="w", pady=(4,0))
            bar_bg = tk.Canvas(parent, bg="#0e0820", height=6, width=170,
                               highlightthickness=0, bd=0)
            bar_bg.grid(row=row*2+1, column=0, columnspan=2,
                        sticky="ew", pady=(1,2))
            fill_w = int(170 * val_pct / 100)
            bar_fill = bar_bg.create_rectangle(0, 0, fill_w, 6,
                                               fill="#d4a017", outline="")
            pct_lbl = tk.Label(parent, text=f"{val_pct}%",
                               bg="#110e1e", fg="#d4a017",
                               font=("Segoe UI", 7))
            pct_lbl.grid(row=row*2+1, column=2, padx=(4,0))
            return bar_bg, bar_fill, pct_lbl

        self.disc_bar_canvas, self.disc_bar, self._disc_pct_lbl = \
            _stat_row(body, "Logic", self.bond.discipline, 0)
        self.focus_bar_canvas, self.focus_bar, self._focus_pct_lbl = \
            _stat_row(body, "Decisiveness", self.bond.focus, 1)

        # Separator
        tk.Frame(align_outer, bg="#1e1040", height=1).pack(fill=tk.X, pady=(0,2))

        # Bottom row — exchanges + status tag
        bottom = tk.Frame(align_outer, bg="#110e1e")
        bottom.pack(fill=tk.X, padx=8, pady=(2,6))

        tk.Label(bottom, text="EXCHANGES",
                 bg="#110e1e", fg="#444444",
                 font=("Segoe UI", 7, "bold")).pack(side=tk.LEFT)
        self.sessions_label = tk.Label(bottom, text=str(self.bond.sessions),
                                       bg="#110e1e", fg="#888888",
                                       font=("Segoe UI", 8, "bold"))
        self.sessions_label.pack(side=tk.LEFT, padx=(4, 0))

        self.stage_label = tk.Label(bottom, text=f"[ {self.bond.stage} ]",
                                    bg="#110e1e", fg="#9b5fd4",
                                    font=("Segoe UI", 8, "bold"))
        self.stage_label.pack(side=tk.RIGHT)

    def _on_canvas_resize(self, event):
        self.chat_canvas.itemconfig(self.chat_canvas_window, width=event.width)
        self.chat_canvas.configure(scrollregion=self.chat_canvas.bbox("all"))

    # ------------------------------------------------------------------
    # Message bubbles
    # ------------------------------------------------------------------

    def _bind_main_scroll(self, widget):
        """Recursively forward scroll events from every bubble child to the canvas."""
        def _scroll(e):
            self.chat_canvas.yview_scroll(-1 * (e.delta // 120), "units")
        def _up(e):
            self.chat_canvas.yview_scroll(-1, "units")
        def _down(e):
            self.chat_canvas.yview_scroll(1, "units")
        widget.bind("<MouseWheel>", _scroll, add="+")
        widget.bind("<Button-4>",   _up,    add="+")
        widget.bind("<Button-5>",   _down,  add="+")
        for child in widget.winfo_children():
            self._bind_main_scroll(child)

    def _add_bubble(self, role: str, text: str, timestamp: str = ""):
        """Add a chat bubble. role = 'user' | 'lelouch'"""
        if not timestamp:
            timestamp = datetime.now().strftime("%H:%M")

        outer = tk.Frame(self.messages_frame, bg=BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        if role == "lelouch":
            # Left-aligned bubble with styled imagery + dialogue split
            bubble_frame = tk.Frame(outer, bg=BG_PANEL)
            bubble_frame.pack(anchor="w", fill=tk.X)

            name_lbl = tk.Label(bubble_frame, text="LELOUCH",
                                 bg=BG_PANEL, fg=LELOUCH_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="w", padx=2)

            bubble = tk.Frame(bubble_frame, bg=LELOUCH_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="w", fill=tk.X)

            # Parse imagery (*...*) and dialogue lines
            imagery_line, dialogue_line = _split_lelouch_response(text)

            if imagery_line:
                img_lbl = tk.Label(
                    bubble, text=f"*{imagery_line}*",
                    bg=LELOUCH_BUBBLE, fg="#c4b5fd",
                    font=("Segoe UI", 10, "italic"),
                    wraplength=480, justify=tk.LEFT, anchor="w"
                )
                img_lbl.pack(anchor="w", pady=(0, 4))

            # If parser found dialogue use it; if only imagery exists show
            # it as dialogue too; last resort show raw text
            display_text = dialogue_line or (text if not imagery_line else "")
            msg_label = tk.Label(
                bubble, text=display_text,
                bg=LELOUCH_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=480, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=LELOUCH_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        else:
            # Right-aligned bubble
            bubble_frame = tk.Frame(outer, bg=BG_PANEL)
            bubble_frame.pack(anchor="e")

            name_lbl = tk.Label(bubble_frame, text="USER",
                                 bg=BG_PANEL, fg=USER_NAME_CLR,
                                 font=("Segoe UI", 8, "bold"))
            name_lbl.pack(anchor="e", padx=2)

            bubble = tk.Frame(bubble_frame, bg=USER_BUBBLE,
                               padx=12, pady=8)
            bubble.pack(anchor="e")

            msg_label = tk.Label(
                bubble, text=text,
                bg=USER_BUBBLE, fg="#ffffff",
                font=("Segoe UI", 11),
                wraplength=380, justify=tk.LEFT, anchor="w"
            )
            msg_label.pack(anchor="w")

            ts_lbl = tk.Label(bubble, text=timestamp,
                               bg=USER_BUBBLE, fg=TIMESTAMP_CLR,
                               font=("Segoe UI", 8))
            ts_lbl.pack(anchor="e")

        # Forward scroll from every bubble widget to the canvas
        self._bind_main_scroll(outer)
        self._scroll_bottom()
        return msg_label  # return label so streaming can update it

    def _scroll_bottom(self):
        self.messages_frame.update_idletasks()
        self.chat_canvas.configure(
            scrollregion=self.chat_canvas.bbox("all"))
        self.chat_canvas.yview_moveto(1.0)

    # ------------------------------------------------------------------
    # Streaming bubble
    # ------------------------------------------------------------------

    def _add_streaming_bubble(self):
        """Add a bubble that will be updated token-by-token."""
        timestamp = datetime.now().strftime("%H:%M")
        outer = tk.Frame(self.messages_frame, bg=BG_PANEL)
        outer.pack(fill=tk.X, padx=10, pady=4)

        name_lbl = tk.Label(outer, text="LELOUCH", bg=BG_PANEL,
                             fg=LELOUCH_NAME_CLR, font=("Segoe UI", 8, "bold"))
        name_lbl.pack(anchor="w", padx=2)

        bubble = tk.Frame(outer, bg=LELOUCH_BUBBLE, padx=12, pady=8)
        bubble.pack(anchor="w", fill=tk.X)

        # Imagery placeholder (italic, lavender)
        self._stream_img_label = tk.Label(
            bubble, text="",
            bg=LELOUCH_BUBBLE, fg="#c4b5fd",
            font=("Segoe UI", 10, "italic"),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_img_label.pack(anchor="w")

        # Dialogue placeholder
        self._stream_label = tk.Label(
            bubble, text="▌",
            bg=LELOUCH_BUBBLE, fg="#ffffff",
            font=("Segoe UI", 11),
            wraplength=480, justify=tk.LEFT, anchor="w"
        )
        self._stream_label.pack(anchor="w")

        self._stream_ts = tk.Label(bubble, text=timestamp,
                                    bg=LELOUCH_BUBBLE, fg=TIMESTAMP_CLR,
                                    font=("Segoe UI", 8))
        self._stream_ts.pack(anchor="e")

        self._stream_text = ""
        self._scroll_bottom()

    def _append_stream_token(self, token: str):
        """Called from background thread — schedules UI update."""
        self._stream_text += token
        self.after(0, self._update_stream_label)

    def _update_stream_label(self):
        if hasattr(self, "_stream_label"):
            imagery_line, dialogue_line = _split_lelouch_response(self._stream_text)
            if imagery_line and hasattr(self, "_stream_img_label"):
                self._stream_img_label.config(text=f"*{imagery_line}*")
                self._stream_label.config(
                    text=(dialogue_line + "▌") if dialogue_line else "▌")
            else:
                self._stream_label.config(text=self._stream_text + "▌")
        self._scroll_bottom()

    def _finalize_stream(self):
        if hasattr(self, "_stream_label") and hasattr(self, "_stream_img_label"):
            final = _normalize_reply(self._stream_text)
            imagery_line, dialogue_line = _split_lelouch_response(final)
            if imagery_line:
                self._stream_img_label.config(text=f"*{imagery_line}*")
            self._stream_label.config(
                text=dialogue_line if dialogue_line else self._stream_text)
        elif hasattr(self, "_stream_label"):
            self._stream_label.config(text=self._stream_text)

    # ------------------------------------------------------------------
    # Send / Chat
    # ------------------------------------------------------------------

    def _send(self):
        if self.is_typing:
            return
        text = self.input_var.get().strip()
        if not text:
            return

        self.input_var.set("")
        ts = datetime.now().strftime("%H:%M")

        # Append to persistent log
        self.history_log.append({"time": ts, "role": "USER", "text": text})
        save_history(self.history_log)

        self._add_bubble("user", text, ts)

        self.is_typing = True
        self.status_var.set("Lelouch is calculating...")
        self.avatar_status.config(text="... processing")

        def run():
            try:
                if self.session.stream:
                    self.after(0, self._add_streaming_bubble)
                    time.sleep(0.05)  # let UI render
                    reply = chat(self.session, text,
                                 stream_callback=self._append_stream_token)
                    self.after(0, self._finalize_stream)
                else:
                    reply = chat(self.session, text)
                    self.after(0, lambda: self._add_bubble("lelouch", reply))
            except Exception as e:
                reply = f"[Error: {e}]"
                self.after(0, lambda: self._add_bubble("lelouch", reply))

            ts2 = datetime.now().strftime("%H:%M")
            self.history_log.append({"time": ts2, "role": "LELOUCH", "text": reply})
            save_history(self.history_log)

            self.bond.update(text, reply)
            self.after(0, self._update_bond_bars)
            self.after(0, lambda: self.status_var.set(
                "Lelouch is listening. Speak with purpose."))
            self.after(0, lambda: self.avatar_status.config(
                text=f"— {self.current_mood.lower()} —"))
            self.after(0, lambda: setattr(self, "is_typing", False))

            # Lelouch farewell — show a goodbye bubble then close
            if re.match(r"^(bye+|goodbye|see you|cya|good night|goodnight)\W*$",
                        text.strip(), re.IGNORECASE):
                farewell = (
                    "*He gives a single measured nod, gaze calm and final.*\n"
                    "Very well, Adi. Rest is also a strategic choice. Return when you are ready to think clearly."
                )
                self.after(1200, lambda: self._add_bubble(
                    "lelouch", farewell, datetime.now().strftime("%H:%M")))
                self.after(30000, self.destroy)

        threading.Thread(target=run, daemon=True).start()

    # ------------------------------------------------------------------
    # Bond bars
    # ------------------------------------------------------------------

    def _update_bond_bars(self):
        dw = int(170 * self.bond.discipline / 100)
        fw = int(170 * self.bond.focus / 100)
        self.disc_bar_canvas.coords(self.disc_bar, 0, 0, dw, 6)
        self.focus_bar_canvas.coords(self.focus_bar, 0, 0, fw, 6)
        self._disc_pct_lbl.config(text=f"{self.bond.discipline}%")
        self._focus_pct_lbl.config(text=f"{self.bond.focus}%")
        self.sessions_label.config(text=str(self.bond.sessions))
        self.stage_label.config(text=f"[ {self.bond.stage} ]")

    # ------------------------------------------------------------------
    # Greeting
    # ------------------------------------------------------------------

    def _post_greeting(self):
        # Check if returning user
        if self.history_log:
            last_user = next((e["text"] for e in reversed(self.history_log)
                              if e.get("role") == "USER"), None)
            if last_user:
                greeting = (
                    "*He glances up without turning his head, expression composed and still.*\n"
                    "You have returned, Adi. Then you are thinking. Good — tell me what it is."
                )
            else:
                greeting = (
                    "*He sets his pen down precisely and regards you with calm, unblinking focus.*\n"
                    "You returned. That tells me something. Now tell me what brought you back."
                )
        else:
            greeting = (
                "*He turns toward you with a measured, unhurried gaze — as if he has been expecting this.*\n"
                "So you are Adi. I have been told you have questions worth answering. Let us see if that is true."
            )
        self.after(300, lambda: self._add_bubble(
            "lelouch", greeting, datetime.now().strftime("%H:%M")
        ))

    # ------------------------------------------------------------------
    # Dialogs
    # ------------------------------------------------------------------

    def _change_mood(self):
        mood = simpledialog.askstring(
            "Set Mood",
            "Enter mode for Lelouch (e.g. 'strategic', 'analytical', 'deliberate'):",
            parent=self
        )
        if mood:
            self.current_mood = mood.strip().capitalize()
            self.session.mood_hint = mood.strip()
            self.mood_btn.config(text=f"  {self.current_mood} —  ")
            self.avatar_status.config(
                text=f"— {self.current_mood.lower()} —")

    def _open_settings(self):
        win = tk.Toplevel(self)
        win.title("⚙ Settings — Lelouch")
        win.configure(bg=BG_DARK)
        win.geometry("340x280")
        win.resizable(False, False)

        def row(label, var, row_n):
            tk.Label(win, text=label, bg=BG_DARK, fg="#ffffff",
                     font=("Segoe UI", 10)).grid(
                row=row_n, column=0, padx=16, pady=8, sticky="w")
            e = tk.Entry(win, textvariable=var, bg=INPUT_BG, fg="#ffffff",
                         insertbackground="#ffffff", relief=tk.FLAT, width=18)
            e.grid(row=row_n, column=1, padx=16, pady=8)

        temp_var  = tk.StringVar(value=str(self.session.temperature))
        tok_var   = tk.StringVar(value=str(self.session.max_tokens))
        hist_var  = tk.StringVar(value=str(self.session.max_history))
        model_var = tk.StringVar(value=self.session.model)

        row("Temperature:", temp_var, 0)
        row("Max Tokens:",  tok_var,  1)
        row("History:",     hist_var, 2)
        row("Model:",       model_var, 3)

        def save():
            try:
                self.session.temperature = float(temp_var.get())
                self.session.max_tokens  = int(tok_var.get())
                self.session.max_history = int(hist_var.get())
                self.session.model       = model_var.get().strip()
                win.destroy()
                self.status_var.set("Settings saved.")
            except ValueError:
                messagebox.showerror("Error", "Invalid value.", parent=win)

        tk.Button(win, text="Save", bg=BUTTON_SEND, fg="#ffffff",
                  relief=tk.FLAT, font=("Segoe UI", 10, "bold"),
                  padx=16, pady=6, command=save,
                  cursor="hand2").grid(row=4, column=0, columnspan=2, pady=12)

